<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Controllers\Controller;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\Cache;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;use Throwable;
class SystemHealthController extends Controller{public function readiness():JsonResponse{$checks=$this->checks();$ok=!in_array(false,$checks,true);return response()->json(['data'=>['status'=>$ok?'ok':'degraded']],$ok?200:503);}public function details(Request $request):JsonResponse{abort_unless($request->user()->is_admin,403);$checks=$this->checks();$files=Storage::disk(config('backup.disk'))->files('backups');$latest=collect($files)->sortByDesc(fn($file)=>Storage::disk(config('backup.disk'))->lastModified($file))->first();return response()->json(['data'=>['status'=>in_array(false,$checks,true)?'degraded':'ok','checks'=>$checks,'latest_backup'=>$latest?['file'=>basename($latest),'created_at'=>date(DATE_ATOM,Storage::disk(config('backup.disk'))->lastModified($latest))]:null]]);}private function checks():array{$checks=[];try{DB::select('select 1');$checks['database']=true;}catch(Throwable){$checks['database']=false;}try{$key='health:'.uniqid();Cache::put($key,'ok',10);$checks['cache']=Cache::get($key)==='ok';Cache::forget($key);}catch(Throwable){$checks['cache']=false;}try{$path='health/'.uniqid();Storage::disk('local')->put($path,'ok');$checks['storage']=Storage::disk('local')->exists($path);Storage::disk('local')->delete($path);}catch(Throwable){$checks['storage']=false;}return $checks;}}
